import React, { useEffect, useState } from "react";
import { AlertTriangle, Loader2 } from "lucide-react";

// The AI reports are generated by a request that lives in this page: refreshing or closing the tab cancels it,
// and the person starts over. These tell them so while it runs, and give them a way forward if it fails.

/** Asks the browser to confirm before the tab is closed or refreshed, for as long as `active` is true. */
export function useLeaveWarning(active: boolean) {
  useEffect(() => {
    if (!active) return;
    const warn = (e: BeforeUnloadEvent) => {
      e.preventDefault();
      e.returnValue = ""; // some browsers only show the prompt when this is set
    };
    window.addEventListener("beforeunload", warn);
    return () => window.removeEventListener("beforeunload", warn);
  }, [active]);
}

export const GenerationNotice: React.FC<{ what: string }> = ({ what }) => {
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    const timer = setInterval(() => setSeconds((s) => s + 1), 1000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div
      role="status"
      data-testid="generation-notice"
      className="flex items-start gap-3 rounded-2xl border border-indigo-500/30 bg-indigo-500/10 px-4 py-3 text-left"
    >
      <Loader2 className="w-5 h-5 mt-0.5 shrink-0 text-indigo-300 animate-spin" />
      <div>
        <p className="text-sm font-semibold text-indigo-100">
          Generating your {what}... {seconds}s
        </p>
        <p className="text-xs text-indigo-200/70 mt-1">
          This can take up to a minute. Please keep this tab open and don't refresh or close the page until it finishes.
        </p>
      </div>
    </div>
  );
};

export const GenerationFailed: React.FC<{ what: string; onRetry: () => void }> = ({ what, onRetry }) => (
  <div
    data-testid="generation-failed"
    className="flex flex-col items-center justify-center text-center p-10 rounded-3xl border border-white/5 bg-slate-900/30"
  >
    <div className="p-4 bg-amber-500/10 rounded-full mb-4">
      <AlertTriangle className="w-8 h-8 text-amber-400" />
    </div>
    <h3 className="text-xl font-bold text-white mb-2">We couldn't generate your {what}</h3>
    <p className="text-slate-400 max-w-sm mb-6 text-sm">
      Your scan is safe. This usually works on a second try. Keep this tab open while it generates.
    </p>
    <button
      type="button"
      onClick={onRetry}
      className="px-6 py-3 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-medium transition-all"
    >
      Try again
    </button>
  </div>
);
